(function($) {
    var ui = kendo.ui,
            MultiSelect = ui.MultiSelect,
            ACCEPT = "accept",
            FILTER = "filter",
            keys = kendo.keys,
            NEXT = "nextSibling",
            PREV = "previousSibling";

    var MultiSelectEx = MultiSelect.extend({
        init: function(element, options) {
            var that = this;
            MultiSelect.fn.init.call(that, element, options);
        },
        options: {
            name: 'MultiSelectEx',
            userInput: true,
            defaultItem: {},
            dataTextField: 'text',
            dataValueField: 'value'
        },
        _keydown: function(e) {
            var that = this,
                    key = e.keyCode,
                    tag = that._currentTag,
                    current = that._current,
                    hasValue = that.input.val(),
                    isRtl = kendo.support.isRtl(that.wrapper),
                    visible = that.popup.visible(),
                    userInput = that.options.userInput;
            if (key === keys.DOWN) {
                e.preventDefault();

                if (!visible) {
                    that.open();
                    return;
                }

                if (current) {
                    current = sibling(current[0], NEXT);
                } else {
                    current = that.ul[0].firstChild;
                }
                
                if (current) {
                    that.current($(current));
                }
            } else if (key === keys.UP) {
                if (visible) {
                    if (current) {
                        current = sibling(current[0], PREV);
                    } else {
                        current = that.ul[0].lastChild;
                    }

                    that.current($(current));

                    if (!that._current[0]) {
                        that.close();
                    }
                }
                e.preventDefault();
            } else if ((key === keys.LEFT && !isRtl) || (key === keys.RIGHT && isRtl)) {
                if (!hasValue) {
                    tag = tag ? tag.prev() : $(that.tagList[0].lastChild);
                    if (tag[0]) {
                        that.currentTag(tag);
                    }
                }
            } else if ((key === keys.RIGHT && !isRtl) || (key === keys.LEFT && isRtl)) {
                if (!hasValue && tag) {
                    tag = tag.next();
                    that.currentTag(tag[0] ? tag : null);
                }
            } else if (key === keys.ENTER) {

                if (visible) {
                    if (current) {
                        
                        that._select(current);
                    }

                    that._change();
                    that.close();
                    e.preventDefault();
                } else if (userInput && hasValue.trim()) {
                    e.preventDefault();
                    if (that._addCustomItem(hasValue)) {
                        current = $(that.ul[0].firstChild);
                        that._select(current);
                        that.currentTag(null);
                        that._filterSource();
                        that._change();
                        that.close();
                    }
                    
                }
            } else if (e.keyCode === 186 || e.keyCode === 188 || e.keyCode === 190) {
                e.preventDefault();
                if (userInput && hasValue.trim()) {
                    if (that._addCustomItem(hasValue)) {
                        current = $(that.ul[0].firstChild);
                        that._select(current);
                        that.currentTag(null);
                        that._filterSource();
                        that._change();
                        that.close();
                    }
                }

            } else if (key === keys.ESC) {
                if (visible) {
                    e.preventDefault();
                } else {
                    that.currentTag(null);
                }

                that.close();
            } else if (key === keys.HOME) {
                if (visible) {
                    that.current($(first(that.ul[0])));
                } else if (!hasValue) {
                    tag = that.tagList[0].firstChild;

                    if (tag) {
                        that.currentTag($(tag));
                    }
                }
            } else if (key === keys.END) {
                if (visible) {
                    that.current($(last(that.ul[0])));
                } else if (!hasValue) {
                    tag = that.tagList[0].lastChild;

                    if (tag) {
                        that.currentTag($(tag));
                    }
                }
            } else if ((key === keys.DELETE || key === keys.BACKSPACE) && !hasValue) {
                if (key === keys.BACKSPACE && !tag) {
                    tag = $(that.tagList[0].lastChild);
                }

                if (tag && tag[0]) {
                    that._unselect(tag);
                    that._change();
                    that.close();
                }
            } else {
                clearTimeout(that._typing);
                that._search();
            }
        },
        _addCustomItem: function(word) {
            var that = this,
                    values = that._values || [],
                    newItem = {};
            
            var idx = $.inArray(word,values);
            if (idx===-1) {
                newItem[that.options.dataTextField] = word;
                newItem[that.options.dataValueField] = word;
                that.dataSource.insert(0, newItem);
            }
            return idx===-1;
        }
    });

    function sibling(item, direction) {
        item = item[direction];

        if (item && item.style.display === "none") {
            item = sibling(item, direction);
        }

        return item;
    }


    ui.plugin(MultiSelectEx);
})(jQuery);